{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "However, studies assessing their effectiveness in delivering primary prevention interventions for non-communicable disease prevention and control in LMIC settings are limited,[10] though this has been proven for developed countries.[11]\nFurther, whatever sparse results are available are mostly through observational studies and evidence from controlled trials needs to be synthesised.\nOnly four systematic reviews assessing this effectiveness in LMIC/ developing countries could be identified after review of published literature.[11-14]",
      "reason": "The current knowledge is described as limited/sparse, but the evidence provided does not clearly articulate specific “important uncertainties” beyond stating that effectiveness parameters need synthesis."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Considering this deficiency in availability of effectiveness parameters, a systematic review on effectiveness of CHW delivered primary prevention interventions for NCDs in developing countries was conducted by the authors.",
      "reason": "The need for conducting the review is explicitly explained as addressing a deficiency in available effectiveness parameters."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Only four systematic reviews assessing this effectiveness in LMIC/ developing countries could be identified after review of published literature.[11-14]",
      "reason": "The existence of similar systematic reviews is acknowledged (though the evidence does not specify updates/replications or cite a specific previous review as the motivation for a new review beyond noting how many were found)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "This was conducted following the hypothesis that for NCD control programs employing a community health worker is more likely to be successful than routine care.",
      "reason": "A hypothesised rationale/mechanistic expectation is stated: CHW-delivered programs are hypothesised to be more successful than routine care."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model depicting hypothesised relationships between intervention components and outcomes is reported in the retrieved evidence."
    }
  ],
  "confidence": 62
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not provide an explicit statement of the review objective(s) or question(s) in a question-formulation framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "Binary outcomes were reported as relative risk (RR) of outcomes in the intervention group compared to the control group. For continuous outcomes, and where baseline data were available, mean difference (MD) between the change in the intervention and control groups were reported.",
      "reason": "The evidence indicates the presence of intervention vs control comparisons in effect estimation, but it does not explicitly state the planned comparisons using PICO (or an appropriate variant) for the review."
    }
  ],
  "confidence": 56
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "A research was considered eligible for inclusion if it followed a randomised controlled study design in community settings of low middle income countries with community health worker as intervention delivery person for general or high risk population for primary prevention of NCDs as compared to routine care or enhanced routine care as comparator.",
      "reason": "The eligibility characteristics are specified for study design (randomised controlled; community settings; CHW intervention; general/high-risk population; primary prevention of NCDs; comparator routine/enhanced routine care). However, the evidence provided does not specify any follow-up requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "Only randomised controlled trials (community based randomised controlled trial, cluster randomised trials) published in the last 15 years (2000-2015) were included in the review. ... without restriction to language:",
      "reason": "Dissemination year (2000–2015) and language (no restriction) are specified. The evidence does not clearly state eligibility criteria for publication/report status (e.g., what counts as eligible published vs unpublished reports)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found describing whether exclusions were distinguished between cases where outcomes were not measured versus cases where outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_17",
      "quote": "Outcomes of interventions identified under the review were grouped into health topics identified in the protocol. ... Meta-analyses were carried out separately for each outcome and type of study design (RCT/ cRCT).",
      "reason": "The evidence describes how outcomes were grouped (health topics) and that meta-analyses were done separately by outcome and study design (RCT/cRCT), but it does not explicitly link these groups to the specific comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although time period and design restrictions are described, the evidence provided does not give rationales specifically for notable restrictions on study eligibility (as required)."
    }
  ],
  "confidence": 58
}

{
