      "element_id": "prisma_2020_6_e7",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "In addition, reference lists and bibliographies of previous systematic and non- systematic reviews were screened and citation tracking were undertaken to identify relevant studies.",
      "reason": "The evidence specifies the kinds of reference lists examined (reference lists and bibliographies of previous systematic and non-systematic reviews)."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Citation tracking is mentioned, but the seed reports, citation index/platform, and the search date are not reported."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No journals or conference proceedings consulted, dates covered, or search methods for them are reported in the provided evidence."
    }
