    {
      "element_id": "prisma_2020_7_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No natural-language processing or text-analysis tools for identifying/refining search terms are specified in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No tools for translating search strings between sources are described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe any validation of the search strategy (process or validation studies)."
    },
    {
      "element_id": "prisma_2020_7_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No peer review of the search strategy (e.g., PRESS) is described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_13",
      "quote": "Due to the diversity of interventions and health topics covered, populations, study types and outcomes, a multi-stage search strategy was developed to identify relevant publications.",
      "reason": "The retrieved evidence does not indicate that the search structure was “not based on PICO.” Instead, it describes a multi-stage strategy, so the specific requirement to report a final conceptual structure/explorations when not using PICO cannot be assessed as applicable based on the provided evidence."
